mapper.select:
select count(*)
from user_account
where login_name = #{loginName}

    or phone = #{phone}

mapper.update:
update user_account
set password_hash = #{passwordHash},
    updated_at = CURRENT_TIMESTAMP
where id = #{staffId}
  and role_code = 'STAFF'
  and venue_id = #{venueId}

mapper.select:
select id, login_name, display_name, phone, role_code, venue_id, status, created_at from user_account

            and role_code = #{roleCode}
            and venue_id = #{venueId}

            and (login_name like concat('%', #{keyword}, '%') or display_name like concat('%', #{keyword}, '%'))


            and status = #{status}


order by created_at desc
